<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {getStudio,type StudioPayload} from './content-studio-api';import {getVisitorState,type VPayload} from './visitor-content-api';import {studioMedia} from '../../shared/studio-media';const images=computed(()=>studio.value&&visitor.value?studioMedia(visitor.value.state.media,studio.value.document):[]);const studio=ref<StudioPayload|null>(null),visitor=ref<VPayload|null>(null),message=ref(''),busy=ref(false);async function load(){[studio.value,visitor.value]=await Promise.all([getStudio(),getVisitorState()])}onMounted(load);const missing=computed(()=>Object.values(studio.value?.document.places||{}).filter(p=>!p.photos.length));async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!visitor.value)return;busy.value=true;try{const slot=`content.library-${crypto.randomUUID()}.asset`,response=await fetch(`/api/admin/visitor-content/visual-media/${encodeURIComponent(slot)}`,{method:'POST',body:file,headers:{'Content-Type':file.type,'X-Media-Version':String(visitor.value.state.media.version),'X-Original-Name':encodeURIComponent(file.name)}});const result=await response.json();if(!response.ok)throw new Error(result.error);message.value=`已上传 ${file.name}。可在地点编辑页关联为封面或图集。`;await load()}catch(e){message.value=(e as Error).message}finally{busy.value=false}}
</script><template><div v-if="studio&&visitor" class="workspace-page studio-page"><div class="workspace-title"><div><p class="kicker">照片与媒体</p><h1>媒体库</h1><p>手机可以直接拍照或从相册选择。上传后的原文件按内容哈希保存，不会同名覆盖。</p></div><label class="button primary-action camera-upload">{{busy?'上传中…':'拍照或上传'}}<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" @change="upload"></label></div><p v-if="message" class="inline-message">{{message}}</p><section><h2>当前图片</h2><div class="media-library-grid"><article v-for="item in images" :key="item.image.id+'|'+item.image.fileName"><img :src="'/api/admin/visitor-content/media/'+item.image.fileName" :alt="item.title"><strong>{{item.title}}</strong><small>{{item.image.mimeType}} · 上传 {{new Date(item.image.uploadedAt).toLocaleString('zh-CN')}}</small><p>1 个资产文件 · {{item.uses.length}} 处照片关联 · {{item.places.length}} 个地点复用（当前草稿）</p><RouterLink v-for="use in item.places" :to="'/studio/places/'+use.placeId">{{use.name}}{{use.archived?'（已归档）':''}}</RouterLink><p v-if="!item.uses.length">当前草稿未引用；可能由已发布内容或历史版本保留。</p><details><summary>高级详情</summary><p>当前草稿计数不含已发布内容及历史版本引用，不能据此删除文件。</p><p>{{item.slots.length}} 个媒体库引用键，不代表图片数量或地点数量。</p><p>资产 ID：{{item.image.id}}</p><p>文件：{{item.image.fileName}}</p><p v-for="slot in item.slots">引用键：{{slot}}</p><p v-for="name in item.names">原名称：{{name}}</p></details></article><p v-if="!Object.keys(visitor.state.media.items).length">媒体库目前为空。</p></div></section><section><h2>缺少图片的地点（{{missing.length}}）</h2><div class="need-list"><RouterLink v-for="p in missing" :to="`/studio/places/${p.id}`">{{p.name.zh}} <small>{{p.id}}</small></RouterLink></div></section></div></template>
